<template><div class="app-container"><el-card><div slot="header">我的持仓</div><el-table :data="rows" row-key="positionId" :expand-row-keys="expanded"><el-table-column width="44"><template slot-scope="s"><el-button class="caret" type="text" @click="toggle(s.row)">{{expanded[0]===s.row.positionId?'∨':'>'}}</el-button></template></el-table-column><el-table-column type="expand" width="1"><template slot-scope="s"><div v-loading="loading[s.row.positionId]" class="panel"><template v-if="report(s.row)"><h3>{{report(s.row).stock.name}} {{report(s.row).stock.code}}</h3><p>现价 {{report(s.row).stock.currentPrice}}，开高低收 {{report(s.row).stock.openPrice}} / {{report(s.row).stock.high}} / {{report(s.row).stock.low}} / {{report(s.row).stock.currentPrice}}</p><p>MA5 / MA20：{{report(s.row).stock.ma5}} / {{report(s.row).stock.ma20}}；20日趋势：{{report(s.row).trendDesc}}</p><p>交易信号：{{report(s.row).signal.description}}；理由：{{report(s.row).signal.reason}}</p><p>持仓成本 {{report(s.row).holding.costAmount}}，市值 {{report(s.row).holding.marketValue}}，浮盈亏 {{report(s.row).holding.profitAmount}}，浮盈亏率 {{report(s.row).holding.profitPct}}%，持仓比例 {{report(s.row).holding.positionPct || '未设置'}}%</p><p v-if="report(s.row).indicators">成交量 {{report(s.row).stock.volume}}，放量倍数 {{report(s.row).indicators.volumeRatio}}，缩量比例 {{report(s.row).indicators.contractionRatio}}，震荡区间 {{report(s.row).indicators.rangeLow}} - {{report(s.row).indicators.rangeHigh}}，大盘趋势 {{report(s.row).indicators.indexTrend}}，板块趋势 暂未接入</p><el-button type="primary" size="small" :loading="aiLoading[s.row.positionId]" @click="analyze(s.row,true)">AI分析</el-button><div v-if="aiShown[s.row.positionId]"><h3>DeepSeek AI 分析报告</h3><p>{{report(s.row).aiAdvice}}</p><p>{{report(s.row).aiReason}}</p></div></template><template v-else><p>暂无已保存分析</p><el-button type="primary" size="small" @click="analyze(s.row,false)">分析</el-button></template></div></template></el-table-column><el-table-column prop="stockCode" label="代码"/><el-table-column prop="costPrice" label="成本价"/><el-table-column prop="quantity" label="持仓数量"/><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="openEdit(s.row)">编辑</el-button><el-button type="text" @click="analyze(s.row,false)">分析</el-button></template></el-table-column></el-table></el-card><el-dialog title="编辑持仓" :visible.sync="visible" width="420px"><el-form :model="edit"><el-form-item label="股票代码"><el-input v-model="edit.stockCode" disabled/></el-form-item><el-form-item label="成本价"><el-input v-model="edit.costPrice"/></el-form-item><el-form-item label="持仓数量"><el-input v-model="edit.quantity"/></el-form-item></el-form><div slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="saveEdit">保存</el-button></div></el-dialog></div></template>
<script>import{listPosition,updatePosition,analyzePosition,getPositionAnalysis}from'@/api/stock/position';export default{name:'StockPosition',data(){return{rows:[],visible:false,edit:{},expanded:[],reports:{},loaded:{},loading:{},aiLoading:{},aiShown:{}}},created(){this.load()},methods:{report(r){return this.reports[r.positionId]},load(){listPosition().then(r=>this.rows=r.data)},openEdit(r){this.edit={positionId:r.positionId,stockCode:r.stockCode,stockName:r.stockName,costPrice:r.costPrice,quantity:r.quantity};this.visible=true},saveEdit(){if(!(this.edit.costPrice>0&&this.edit.quantity>0))return this.$modal.msgWarning('成本价和数量必须大于零');updatePosition(this.edit).then(()=>{this.$modal.msgSuccess('保存成功');this.visible=false;this.load()})},toggle(r){const id=r.positionId;if(this.expanded[0]===id){this.expanded=[];return}this.expanded=[id];if(this.loaded[id])return;this.$set(this.loading,id,true);getPositionAnalysis(id).then(x=>{if(x.data)this.$set(this.reports,id,x.data);this.$set(this.aiShown,id,!!(x.data&&x.data.aiAdvice));this.$set(this.loaded,id,true)}).finally(()=>this.$set(this.loading,id,false))},analyze(r,ai){const id=r.positionId;this.expanded=[id];this.$set(ai?this.aiLoading:this.loading,id,true);analyzePosition(id,ai).then(x=>{this.$set(this.reports,id,x.data);this.$set(this.loaded,id,true);this.$set(this.aiShown,id,!!x.data.aiAdvice)}).finally(()=>this.$set(ai?this.aiLoading:this.loading,id,false))}}}</script><style scoped>.panel{padding:16px;background:#fafafa;line-height:1.8}.caret{font-size:18px;padding:0;min-width:24px}</style>
